<?php
require_once __DIR__ . '/../includes/course_unlock.php';
$user=require_role(ROLE_TEACHER);$tid=(int)$user['id'];$pdo=db();$error='';$ok='';
$cid=positive_int($_GET['course_id']??$_POST['course_id']??null);
$st=$pdo->prepare('SELECT id,title,level FROM courses WHERE id=:id AND teacher_id=:tid');$st->execute(['id'=>$cid,'tid'=>$tid]);$course=$st->fetch(PDO::FETCH_ASSOC);
if(!$course){http_response_code(403);exit('Khóa học không tồn tại hoặc bạn không sở hữu khóa học này.');}
if($course['level']==='beginner'){http_response_code(422);exit('Khóa Cơ bản không cần khóa học tiên quyết.');}
$levelBefore=$course['level']==='intermediate'?'beginner':'intermediate';
$st=$pdo->prepare('SELECT id,title FROM courses WHERE teacher_id=:tid AND level=:lvl AND id<>:cid ORDER BY title');$st->execute(['tid'=>$tid,'lvl'=>$levelBefore,'cid'=>$cid]);$previousCourses=$st->fetchAll(PDO::FETCH_ASSOC);
$st=$pdo->prepare("SELECT ex.id,ex.title,ch.course_id FROM exercises ex JOIN lessons l ON l.id=ex.lesson_id JOIN course_chapters ch ON ch.id=l.chapter_id JOIN courses c ON c.id=ch.course_id WHERE c.teacher_id=:tid AND c.level=:lvl AND ex.exercise_type='quiz' ORDER BY c.title,ex.title");$st->execute(['tid'=>$tid,'lvl'=>$levelBefore]);$tests=$st->fetchAll(PDO::FETCH_ASSOC);
if(is_post()){
 require_csrf();$action=(string)($_POST['action']??'');
 if($action==='delete'){
  $st=$pdo->prepare('DELETE FROM course_unlock_rules WHERE course_id=:cid');$st->execute(['cid'=>$cid]);$ok='Đã xóa điều kiện. Khóa học sẽ ẩn với học viên cho đến khi đặt lại.';
 }elseif($action==='save'){
  $previous=positive_int($_POST['prerequisite_course_id']??null);
  $test=positive_int($_POST['required_test_exercise_id']??null);
  $min=filter_var($_POST['min_score_percent']??null,FILTER_VALIDATE_FLOAT);
  $validPrev=false;foreach($previousCourses as $v){if((int)$v['id']===$previous){$validPrev=true;break;}}
  $validTest=false;foreach($tests as $v){if((int)$v['id']===$test&&(int)$v['course_id']===$previous){$validTest=true;break;}}
  if(!$validPrev||!$validTest||$min===false||$min<0||$min>100){$error='Hãy chọn khóa trước đúng trình độ, bài test trắc nghiệm thuộc khóa đó và điểm đạt 0–100%.';}
  else {
   try{$st=$pdo->prepare('INSERT INTO course_unlock_rules(course_id,prerequisite_course_id,required_test_exercise_id,min_score_percent) VALUES(:cid,:prev,:test,:min) ON DUPLICATE KEY UPDATE prerequisite_course_id=VALUES(prerequisite_course_id),required_test_exercise_id=VALUES(required_test_exercise_id),min_score_percent=VALUES(min_score_percent)');$st->execute(['cid'=>$cid,'prev'=>$previous,'test'=>$test,'min'=>$min]);$ok='Đã lưu điều kiện mở khóa.';}catch(Throwable $exc){error_log('[BrightFuture unlock rules] '.$exc->getMessage());$error='Không lưu được, kiểm tra SQL migration.';}
  }
 }else{$error='Thao tác không hợp lệ.';}
}
$st=$pdo->prepare('SELECT * FROM course_unlock_rules WHERE course_id=:id');$st->execute(['id'=>$cid]);$rule=$st->fetch(PDO::FETCH_ASSOC)?:[];
?><!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Thiết lập lộ trình</title><style>body{font-family:system-ui,sans-serif;background:#f3f5fc;color:#17213a;margin:0}.wrap{max-width:740px;margin:45px auto;padding:25px;background:#fff;border-radius:16px;box-shadow:0 6px 30px #14213d0f}label{display:block;margin:20px 0;font-weight:600}select,input{display:block;width:100%;padding:12px;border:1px solid #d9dfeb;border-radius:9px;margin-top:7px}button,.btn{display:inline-block;border:0;border-radius:9px;padding:12px 18px;background:#5046e5;color:white;text-decoration:none;cursor:pointer}.alert{background:#fff1f2;padding:12px;border-radius:9px}.ok{background:#ecfdf5}p{color:#64748b;line-height:1.6}</style></head><body><main class="wrap"><a href="<?=e(app_url('teacher/courses.php'))?>">← Khóa học của tôi</a><h1>Điều kiện mở khóa</h1><h2><?=e($course['title'])?></h2><p>Học viên chỉ thấy khóa học này sau khi đã hoàn thành mọi bài giảng công khai của khóa trước và đạt bài kiểm tra được chọn.</p><?php if($error):?><div class="alert"><?=e($error)?></div><?php endif?><?php if($ok):?><div class="alert ok"><?=e($ok)?></div><?php endif?>
<form method="POST"><?=csrf_field()?><input type="hidden" name="action" value="save"><input type="hidden" name="course_id" value="<?=$cid?>"><label>Khóa học tiên quyết (<?=e($levelBefore)?>)<select name="prerequisite_course_id" id="prereq" required><option value="">Chọn khóa học</option><?php foreach($previousCourses as $pc):?><option value="<?=(int)$pc['id']?>" <?=(int)($rule['prerequisite_course_id']??0)===(int)$pc['id']?'selected':''?>><?=e($pc['title'])?></option><?php endforeach?></select></label><label>Bài kiểm tra cuối khóa (trắc nghiệm)<select name="required_test_exercise_id" id="test" required><option value="">Chọn bài kiểm tra</option><?php foreach($tests as $t):?><option data-course="<?=(int)$t['course_id']?>" value="<?=(int)$t['id']?>" <?=(int)($rule['required_test_exercise_id']??0)===(int)$t['id']?'selected':''?>><?=e($t['title'])?></option><?php endforeach?></select></label><label>Điểm đạt tối thiểu (%)<input type="number" name="min_score_percent" min="0" max="100" step="0.01" value="<?=e((string)($rule['min_score_percent']??70))?>" required></label><button type="submit">Lưu điều kiện mở khóa</button></form>
<?php if($rule):?><form method="POST" style="margin-top:14px" onsubmit="return confirm('Xóa điều kiện? Khóa này sẽ ẩn với học viên.');"><?=csrf_field()?><input type="hidden" name="course_id" value="<?=$cid?>"><input type="hidden" name="action" value="delete"><button style="background:#b91c1c" type="submit">Xóa điều kiện</button></form><?php endif?><p>Để tạo bài test, vào Quản lý bài tập → chọn loại Trắc nghiệm (quiz), công khai bài test và chấm điểm. Nếu chưa có khóa trước hoặc bài test, các danh sách ở đây sẽ trống.</p></main><script>let p=document.getElementById('prereq'),t=document.getElementById('test');function showTests(){let v=p.value;Array.from(t.options).forEach(o=>{if(o.value){o.hidden=o.dataset.course!==v;if(o.hidden&&o.selected)t.value=''}})}p.addEventListener('change',showTests);showTests();</script></body></html>
